// #Sireum

package drone_lifecycle_governor.Drone_Lifecycle_Governor

import org.sireum._
import art._
import drone_lifecycle_governor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Controlled_Outcome_Derivation_Api {
  def id: Art.BridgeId
  def selected_phase_Id : Art.PortId
  def lifecycle_actuation_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var lifecycle_actuation: Drone_Lifecycle_Governor.Lifecycle_Actuation = $

  def put_lifecycle_actuation(value : Drone_Lifecycle_Governor.Lifecycle_Actuation) : Unit = {
    Contract(
      Modifies(lifecycle_actuation),
      Ensures(
        lifecycle_actuation == value
      )
    )
    Spec {
      lifecycle_actuation = value
    }

    Art.putValue(lifecycle_actuation_Id, Drone_Lifecycle_Governor.Lifecycle_Actuation_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Controlled_Outcome_Derivation_Initialization_Api (
  val id: Art.BridgeId,
  val selected_phase_Id : Art.PortId,
  val lifecycle_actuation_Id : Art.PortId) extends Controlled_Outcome_Derivation_Api

@datatype class Controlled_Outcome_Derivation_Operational_Api (
  val id: Art.BridgeId,
  val selected_phase_Id : Art.PortId,
  val lifecycle_actuation_Id : Art.PortId) extends Controlled_Outcome_Derivation_Api {

  // Logika spec var representing port state for incoming data port
  @spec var selected_phase: Drone_Lifecycle_Governor.Lifecycle_Phase.Type = $

  def get_selected_phase() : Option[Drone_Lifecycle_Governor.Lifecycle_Phase.Type] = {
    Contract(
      Ensures(
        Res == Some(selected_phase)
      )
    )
    val value : Option[Drone_Lifecycle_Governor.Lifecycle_Phase.Type] = Art.getValue(selected_phase_Id) match {
      case Some(Drone_Lifecycle_Governor.Lifecycle_Phase_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port selected_phase.  Expecting 'Drone_Lifecycle_Governor.Lifecycle_Phase_Payload' but received ${v}")
        None[Drone_Lifecycle_Governor.Lifecycle_Phase.Type]()
      case _ => None[Drone_Lifecycle_Governor.Lifecycle_Phase.Type]()
    }
    return value
  }
}
